            color = row[c - 1]
            if color and row[c] == 0 and row[c + 1] == color:
                events[c].append((r, color, False))

    # A vertical colored segment touching the bottom projects upward toward
    # the horizontal rays.
    for c in range(w):
        r = h - 1
        if grid[r][c] == 0:
            continue
        color = grid[r][c]
        while r > 0 and grid[r - 1][c] == color:
            r -= 1
        events[c].append((r, color, True))

    for c in range(w):
        ev = sorted(events[c], key=lambda x: x[0])
        previous = -1
        for r, color, is_bottom in ev:
            end = h - 1 if is_bottom else r
            for rr in range(previous + 1, end + 1):
                if grid[rr][c] == 0:
                    out[rr][c] = color
            previous = end

    return out
